session_start();include('dbstring.php');include_once('online-admission-utils.php');
$ref=trim((string)(isset($_GET['reference'])?$_GET['reference']:''));if($ref==='')exit('Payment reference missing.');$re=mysqli_real_escape_string($con,$ref);$p=mysqli_query($con,"SELECT * FROM tblstudentonlinepayment WHERE referenceid='$re' LIMIT 1");$payment=$p?mysqli_fetch_assoc($p):null;if(!$payment)exit('Payment record not found.');if($payment['status']==='success'){$_SESSION['Message']='Payment was already confirmed.';header('Location:student-fee-payment.php');exit();}$cfg=online_admission_paystack_config();$err='';$v=online_admission_paystack_verify($cfg,$ref,$err);$data=($v&&isset($v['data'])&&is_array($v['data']))?$v['data']:null;if(!$data||strtolower((string)$data['status'])!=='success'||(int)$data['amount']!==(int)round(((float)$payment['amount'])*100)||strtoupper((string)$data['currency'])!=='GHS'){mysqli_query($con,"UPDATE tblstudentonlinepayment SET status='failed' WHERE referenceid='$re'");exit('Payment could not be verified. No bills were credited.');}
mysqli_begin_transaction($con);$ok=true;$uid=mysqli_real_escape_string($con,$payment['userid']);$tx='ONL_'.strtoupper(substr(sha1(uniqid('',true)),0,18));$txe=mysqli_real_escape_string($con,$tx);$actor=mysqli_real_escape_string($con,$payment['userid']);$ok=$ok&&mysqli_query($con,"INSERT INTO tbltransaction(transactionid,userid,datetimepayment,recordedby,status) VALUES('$txe','$uid',NOW(),'$actor','active')");$b=mysqli_query($con,"SELECT billid,amount FROM tblstudentonlinepaymentbill WHERE referenceid='$re'");while($ok&&$b&&($row=mysqli_fetch_assoc($b))){$bill=mysqli_real_escape_string($con,$row['billid']);$due=(float)$row['amount'];$balq=mysqli_query($con,"SELECT bi.cost-COALESCE(SUM(pm.payment),0) bal FROM tblbilling bi LEFT JOIN tblpayment pm ON pm.billid=bi.billid AND pm.status='active' WHERE bi.billid='$bill' GROUP BY bi.billid,bi.cost");$br=$balq?mysqli_fetch_assoc($balq):null;$credit=min($due,max(0,(float)(isset($br['bal'])?$br['bal']:0)));if($credit>0){$pid='PAY_'.strtoupper(substr(sha1(uniqid('',true)),0,18));$ok=$ok&&mysqli_query($con,"INSERT INTO tblpayment(paymentid,userid,billid,transactionid,payment,datetimepayment,recordedby,status,referenceid) VALUES('$pid','$uid','$bill','$txe',$credit,NOW(),'$actor','active','$re')");}}
if($ok){mysqli_query($con,"UPDATE tblstudentonlinepayment SET status='success',paidat=NOW() WHERE referenceid='$re'");mysqli_commit($con);$_SESSION['Message']='Payment confirmed and your selected bills have been updated.';header('Location:student-fee-payment.php');exit();}mysqli_rollback($con);exit('Payment was verified but could not be credited. Please contact the school with reference '.htmlspecialchars($ref).'.');
